    /\b(?:sk|pk|xox[baprs]|ghp|github_pat)_[A-Za-z0-9_=-]{16,}/,
    /\b[A-Za-z0-9._%+-]+=(?:['"])?[A-Za-z0-9/+_=-]{24,}/,
    /\bapi[_-]?key\b\s*[:=]\s*['"]?[A-Za-z0-9_=-]{16,}/i
  ].some((re) => re.test(text));
}

