export function fmtCountdown(untilTs: number, now: number): string {
  const ms = untilTs - now;
  if (ms <= 0) return 'now';
  const mins = Math.floor(ms / 60_000);
  if (mins < 1) return '<1m';
  const h = Math.floor(mins / 60);
  const m = mins % 60;
  return h > 0 ? `${h}h ${m}m` : `${m}m`;
}

